function cleanTitle(title) {
  return title.replace(/^LV\d+(?:_\d+)?\s*/i, '')
    .replace(/^Live 얌얌코딩 \(게임 개발\)\s*-\s*/i, '')
    .replace(/\s*#[\p{L}\p{N}_]+/gu, '')
    .replace(/Directx/gi, 'DirectX').replace(/WINAPI/gi, 'WinAPI')
    .replace(/이해히기/g, '이해하기').replace(/엑터/g, '액터')
    .replace(/Vertext/g, 'Vertex').replace(/백터/g, '벡터')
    .replace(/뺼셈/g, '뺄셈').replace(/슷자의/g, '숫자의')
    .replace(/애파인/g, '아핀').replace(/메테리얼/g, '머티리얼')
    .replace(/데이타/g, '데이터').replace(/메모리 릭/g, '메모리 누수')
    .replace(/Destoryed/g, 'Destroyed').replace(/UIHUd/g, 'UIHUD')
    .replace(/\s+/g, ' ').trim();
}

function headlineFor(change) {
  if (overrides[change.id]) return overrides[change.id];
  let t = cleanTitle(change.originalTitle);
  if (change.category === '게임 포트폴리오') {
    t = t.replace(/^(?:DirectX\s*[23]D?|DX2D|WinAPI|WindowsAPI|Win API)\s*/i, '')
      .replace(/포트폴리오\s*/g, '').replace(/모작/g, '').trim();
    return `${t || '게임 구현 발표'}\n${/모작/.test(change.originalTitle) ? '모작 포트폴리오' : '게임 포트폴리오'}`;
  }
  if (/Solved[ .]?ac/i.test(t)) {
    const number = t.match(/(?:ac\s*|\.ac\s*)(\d+)/i)?.[1] || '';
    const topic = t.replace(/Solved[ .]?ac\s*\d+\s*(?:번)?/ig, '')
      .replace(/\(?C\+\+\)?/ig, '').replace(/solved ac/ig, '').trim();
    return `${topic}\n백준 ${number} · C++`;
  }
  t = t.replace(/^게임 프로그래밍 패턴\s*-\s*/i, '')
    .replace(/^언리얼(?:엔진| 엔진)\s*5\s*[-·]?\s*/i, '')
    .replace(/^부록(?:\(API\))?[.]\s*/, '');
  if (t.length > 38) {
    t = t.replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim();
  }
  return t;
}

